@extends('layouts.storefront') @section('title','Your Bag — AMER') @section('content')<section class="commerce-page"><div class="commerce-title"><p class="eyebrow">YOUR SELECTION</p><h1>Shopping bag</h1></div>@if(session('status'))<p class="commerce-notice">{{ session('status') }}</p>@endif @if($items)<div class="cart-layout"><div>@foreach($items as $item)<article class="cart-line">@if($item['image'])<img src="{{ asset('storage/'.$item['image']) }}" alt="{{ $item['name'] }}">@else<div class="mini-placeholder">AMER</div>@endif<div><a href="{{ route('product.show',$item['slug']) }}"><strong>{{ $item['name'] }}</strong></a><p>{{ $item['variant'] ?: $item['sku'] }}</p><form method="post" action="{{ route('cart.update',$item['variant_id']) }}">@csrf @method('PATCH')<input type="number" name="quantity" value="{{ $item['quantity'] }}" min="0" max="99"><button>Update</button></form></div><div><strong>৳{{ number_format($item['price']*$item['quantity'],0) }}</strong><form method="post" action="{{ route('cart.destroy',$item['variant_id']) }}">@csrf @method('DELETE')<button>Remove</button></form></div></article>@endforeach</div><aside class="order-summary"><h2>Order summary</h2><div><span>Subtotal</span><strong>৳{{ number_format($subtotal,0) }}</strong></div><p>Delivery is calculated at checkout.</p><a class="btn dark full" href="{{ route('checkout.create') }}">Continue to checkout</a></aside></div>@else<div class="empty"><h2>Your bag is empty</h2><a class="btn dark" href="{{ route('shop') }}">Explore products</a></div>@endif</section>@endsection
